 94	            throw notAllowed(reservation, "check in");
 95	        }
 96	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
 97	        store.update(reservation);
 98	        return reservation;
 99	    }
100	
101	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
102	    public synchronized ReservationReceipt checkOut(long reservationId) {
103	        Reservation reservation = find(reservationId);
104	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
105	            throw notAllowed(reservation, "check out");
106	        }
107	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
108	        store.update(reservation);
109	        return new ReservationReceipt(reservation, roomOf(reservation));
110	    }
111	
112	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
113	    public ReservationReceipt receiptCopy(long reservationId) {
114	        Reservation reservation = find(reservationId);
115	        if (!reservation.isPaid()) {
116	            throw notAllowed(reservation, "issue a receipt for");
117	        }
118	        return new ReservationReceipt(reservation, roomOf(reservation));
119	    }
120	
121	    private Room roomOf(Reservation reservation) {
122	        return rooms.find(reservation.roomNumber()).orElseThrow();
123	    }
124	
125	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
126	        return "Olá, " + reservation.guest().name() + "!\n\n"
127	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
128	                + receipt.text() + "\n"
129	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
130	                + "Até breve!\n";
131	    }
132	
133	    private static HotelException notAllowed(Reservation reservation, String operation) {
134	        return new HotelException(
135	                ErrorCode.OPERATION_NOT_ALLOWED,
136	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
137	    }
138	}
139	package hotel.reservations;
140	
141	import java.math.BigDecimal;
142	import java.sql.Connection;
143	import java.sql.Date;
144	import java.sql.PreparedStatement;
145	import java.sql.ResultSet;
146	import java.sql.SQLException;
147	import java.time.LocalDate;
148	import java.util.ArrayList;
149	import java.util.List;
150	import java.util.Optional;
151	import javax.sql.DataSource;
152	
153	/** Keeps the reservations in the database. */
154	public final class ReservationStore {
155	
156	    private static final String COLUMNS = "id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
157	            + "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund";
158	    /** PostgreSQL's code for a broken exclusion constraint: here, the room was already booked on one of the nights. */
159	    private static final String EXCLUSION_VIOLATION = "23P01";
160	
161	    private final DataSource dataSource;
162	
163	    public ReservationStore(DataSource dataSource) {
164	        this.dataSource = dataSource;
165	    }
166	
167	    /** Saves a new reservation; the database numbers it. */
168	    Reservation add(NewReservation request, Price price) {
169	        String insert = "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, "
170	                + "check_out, guests, rate_plan, nights, subtotal, discount, total, status, amount_paid) "
171	                + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) RETURNING id";
172	        try (Connection connection = dataSource.getConnection();
173	                PreparedStatement statement = connection.prepareStatement(insert)) {
174	            statement.setInt(1, request.roomNumber());
175	            statement.setString(2, request.guest().name());
176	            statement.setString(3, request.guest().email());
177	            statement.setString(4, request.guest().cpf());
178	            statement.setDate(5, Date.valueOf(request.checkIn()));
179	            statement.setDate(6, Date.valueOf(request.checkOut()));
180	            statement.setInt(7, request.guests());
181	            statement.setString(8, request.ratePlan().name());
182	            statement.setInt(9, price.nights());
183	            statement.setBigDecimal(10, price.subtotal());
184	            statement.setBigDecimal(11, price.discount());
185	            statement.setBigDecimal(12, price.total());
186	            statement.setString(13, ReservationStatus.PENDING.name());
187	            statement.setBigDecimal(14, PriceCalculator.cents(BigDecimal.ZERO));
188	            try (ResultSet generated = statement.executeQuery()) {
189	                generated.next();
190	                return new Reservation(generated.getLong("id"), request, price);
191	            }
192	        } catch (SQLException failure) {
193	            if (EXCLUSION_VIOLATION.equals(failure.getSQLState())) {
194	                throw new HotelException(ErrorCode.ROOM_UNAVAILABLE,
195	                        "room " + request.roomNumber() + " is taken on some of those nights");
196	            }
197	            throw new IllegalStateException("could not save the reservation", failure);
198	        }
199	    }
200	
201	    /** Saves what changes in a reservation's life: the status, what was paid and what went back. */
202	    void update(Reservation reservation) {
203	        try (Connection connection = dataSource.getConnection();
204	                PreparedStatement statement = connection.prepareStatement(
205	                        "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
206	            statement.setString(1, reservation.status().name());
207	            statement.setBigDecimal(2, reservation.amountPaid());
208	            statement.setBigDecimal(3, reservation.refund());
209	            statement.setLong(4, reservation.id());
210	            statement.executeUpdate();
211	        } catch (SQLException failure) {
212	            throw new IllegalStateException("could not save reservation " + reservation.id(), failure);
213	        }
214	    }
215	
216	    /** Whether a reservation that was not cancelled holds the room on any of the nights. */
217	    boolean isRoomTaken(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
218	        try (Connection connection = dataSource.getConnection();
219	                PreparedStatement select = connection.prepareStatement(
220	                        "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
221	                                + "AND check_in < ? AND ? < check_out")) {
222	            select.setInt(1, roomNumber);
223	            select.setDate(2, Date.valueOf(checkOut));
224	            select.setDate(3, Date.valueOf(checkIn));
225	            try (ResultSet rows = select.executeQuery()) {
226	                return rows.next();
227	            }
228	        } catch (SQLException failure) {
229	            throw new IllegalStateException("could not check room " + roomNumber, failure);
230	        }
231	    }
232	
233	    public Optional<Reservation> find(long id) {
234	        try (Connection connection = dataSource.getConnection();
235	                PreparedStatement select = connection.prepareStatement(
236	                        "SELECT " + COLUMNS + " FROM reservations WHERE id = ?")) {
237	            select.setLong(1, id);
238	            try (ResultSet rows = select.executeQuery()) {
239	                return rows.next() ? Optional.of(read(rows)) : Optional.empty();
240	            }
241	        } catch (SQLException failure) {
242	            throw new IllegalStateException("could not read reservation " + id, failure);
243	        }
244	    }
245	
246	    public List<Reservation> all() {
247	        try (Connection connection = dataSource.getConnection();
248	                PreparedStatement select = connection.prepareStatement(
249	                        "SELECT " + COLUMNS + " FROM reservations ORDER BY id");
250	                ResultSet rows = select.executeQuery()) {
251	            List<Reservation> reservations = new ArrayList<>();
252	            while (rows.next()) {
253	                reservations.add(read(rows));
254	            }
255	            return reservations;
256	        } catch (SQLException failure) {
257	            throw new IllegalStateException("could not read the reservations", failure);
258	        }
259	    }
260	
261	    private static Reservation read(ResultSet row) throws SQLException {
262	        Guest guest = new Guest(row.getString("guest_name"), row.getString("guest_email"), row.getString("guest_cpf"));
263	        NewReservation request = new NewReservation(
264	                row.getInt("room_number"),
265	                guest,
266	                row.getDate("check_in").toLocalDate(),
267	                row.getDate("check_out").toLocalDate(),
268	                row.getInt("guests"),
269	                RatePlan.valueOf(row.getString("rate_plan")));
270	        Price price = new Price(
271	                row.getInt("nights"), row.getBigDecimal("subtotal"), row.getBigDecimal("discount"),
272	                row.getBigDecimal("total"));
273	        return new Reservation(
274	                row.getLong("id"),
275	                request,
276	                price,
277	                ReservationStatus.valueOf(row.getString("status")),
278	                row.getBigDecimal("amount_paid"),
279	                row.getBigDecimal("refund"));
280	    }
281	}

